head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[localStorage > M > setItem]<br/>localStorage 에 key-value 형태로 데이터를 저장합니다.",
    "validation" : [
        "key(필수) 파라미터로 저장할 항목의 키 이름을 설정할 수 있어야 합니다.",
        "key(필수) 파라미터는 반드시 영문자로 시작하여야 합니다.",
        "key(필수) 파라미터에 세미콜론(;)을 포함할 수 없어야 합니다.",
        "key(필수) 파라미터에 'websquare_localStorage_keyList' 예약 키를 사용할 수 없어야 합니다.",
        "value(필수) 파라미터로 저장할 값을 설정할 수 있어야 합니다.",
        "이미 존재하는 키값으로 실행하면 기존 값을 덮어써야 합니다.",
        "key 파라미터의 유효성 검사에 실패하면 데이터가 저장되지 않아야 합니다.",
    ]
}



scwin.onpageload = function () {
    $c.gcm.createCommonDatalist();
    wf_body_left.getObj("scwin").createValidation(scwin.tData);

    // 기존 데이터 초기화
    WebSquare.localStorage.clear();
};



scwin.btn_setItem_onclick = function () {
    let key = par_key.getValue();
    let value = par_value.getValue();

    WebSquare.localStorage.setItem(key, value);

    // 저장 결과 확인 (getItem 으로 검증)
    let stored = WebSquare.localStorage.getItem(key);
    wf_body_bottom.getObj("scwin").setReturnValue("setItem('" + key + "', '" + value + "') 호출");
    wf_body_bottom.getObj("scwin").setReturnValue("getItem('" + key + "') : '" + stored + "'");

    // 유효하지 않은 키인 경우 저장 차단 확인
    var isInvalidKey = /^[^a-zA-Z]/.test(key) || key.indexOf(';') >= 0 || key === 'websquare_localStorage_keyList';
    if (isInvalidKey) {
        wf_body_bottom.getObj("scwin").setReturnValue("유효하지 않은 키 → 저장 차단 확인 : " + (!stored ? "PASS" : "FAIL"));
    } else {
        wf_body_bottom.getObj("scwin").setReturnValue("저장 확인 : " + (stored === value ? "PASS" : "FAIL"));
    }
}



scwin.btn_setItem_overwrite_onclick = function () {
    let key = "testKey";

    // 기존값 저장
    WebSquare.localStorage.setItem(key, "원래값");
    let before = WebSquare.localStorage.getItem(key);

    // 덮어쓰기
    WebSquare.localStorage.setItem(key, "변경된값");
    let after = WebSquare.localStorage.getItem(key);

    wf_body_bottom.getObj("scwin").setReturnValue("덮어쓰기 테스트");
    wf_body_bottom.getObj("scwin").setReturnValue("1차 저장 후 : '" + before + "'");
    wf_body_bottom.getObj("scwin").setReturnValue("2차 저장 후 : '" + after + "'");
    wf_body_bottom.getObj("scwin").setReturnValue("덮어쓰기 확인 : " + (after === "변경된값" ? "PASS" : "FAIL"));

    // 정리
    WebSquare.localStorage.removeItem(key);
}
